using LittleLeo;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "CosmicWisdomAction", menuName = "Data/Battle/Battle Actions/Moonie/CosmicWisdom Action")]
public class CosmicWisdomAction : ChooseCorruptPurifyDieAction
{
	[Header("Action Specifics")]
	[SerializeField]
	private PurifyAction purifyAction;

	[SerializeField]
	private bool enableVFXDelay;

	[SerializeField]
	[ShowIf("enableVFXDelay")]
	private float vfxDelay;

	[SerializeField]
	private bool enableSecondVFXDelay;

	[SerializeField]
	[ShowIf("enableSecondVFXDelay")]
	private float secondVfxDelay;

	[SerializeField]
	private bool chooseDice;

	public PurifyAction PurifyAction => purifyAction;

	public override void Cast(GameObject source)
	{
		if (diceList.Count == 0)
		{
			for (int i = 0; i < ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceInHandAmount(); i++)
			{
				diceList.Add(ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceInstanceFromHand(i));
			}
			if (base.UseOnEnemiesAndCompanions)
			{
				diceList.AddRange(base.currentCorruptedAnimals.GetEnemiesDiceInstances());
				diceList.AddRange(base.currentCompanions.GetSentinelsDiceInstances());
			}
			DefaultCast(goBackToDiceTray: false);
		}
		else
		{
			DefaultCast(goBackToDiceTray: true);
		}
	}

	private void DefaultCast(bool goBackToDiceTray)
	{
		ReferenceSingleton<GameStateManager>.Instance.SetNoInteractionState();
		for (int i = 0; i < diceList.Count; i++)
		{
			bool flag = false;
			DiceInstance diceInstance = diceList[i];
			if (IsCorruptPurifyAction(diceInstance.ActionFace.BattleAction))
			{
				diceInstance.ActionFace.ActionValue = 1;
				diceInstance.ActionFace.BattleAction = purifyAction;
				flag = true;
			}
			if (diceInstance.ActionFace.EnableSecondAction && IsCorruptPurifyAction(diceInstance.ActionFace.SecondBattleAction))
			{
				diceInstance.ActionFace.SecondActionValue = 1;
				diceInstance.ActionFace.SecondBattleAction = purifyAction;
				flag = true;
			}
			if (!flag)
			{
				continue;
			}
			if (enableVFXDelay && !chooseDice)
			{
				InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, vfxDelay, delegate
				{
					SpawnVFXAndUpdateDiceInstance(goBackToDiceTray, i, diceInstance);
				});
			}
			else
			{
				SpawnVFXAndUpdateDiceInstance(goBackToDiceTray, i, diceInstance);
			}
		}
		if (enableSecondVFXDelay)
		{
			InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, secondVfxDelay, delegate
			{
				SpawnSecondVFXOnPlayerPosition(6f);
			});
		}
		else
		{
			SpawnSecondVFXOnPlayerPosition(6f);
		}
		if (IsVFXEnabled())
		{
			PlaySFX();
		}
		if (enableVFXDelay)
		{
			if (chooseDice)
			{
				ReferenceSingleton<PlayerDiceHandPositioningAnimationManager>.Instance.UpdateDiceInHandPosition();
			}
			InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, vfxDelay, delegate
			{
				if (chooseDice)
				{
					for (int j = 0; j < diceList.Count; j++)
					{
						SpawnVFXAndUpdateDiceInstance(diceList[j]);
					}
					EndOfActionAndReset(goBackToDiceTray);
				}
				else
				{
					EndOfActionAndReset(goBackToDiceTray);
				}
			});
		}
		else
		{
			EndOfActionAndReset(goBackToDiceTray);
		}
	}

	private bool IsCorruptPurifyAction(BattleAction battleAction)
	{
		if (interactWithCorruptAction)
		{
			return battleAction is CorruptAction;
		}
		return battleAction is PurifyAction;
	}

	private void SpawnVFXAndUpdateDiceInstance(bool goBackToDiceTray, int i, DiceInstance diceInstance)
	{
		if (goBackToDiceTray)
		{
			if (chooseDice)
			{
				SetDiceInstanceGoBackToOriginalPositionAnimation(goBackToDiceTray, i, diceInstance, null, dontTryToGoToChooseActionState: true);
				return;
			}
			SetDiceInstanceGoBackToOriginalPositionAnimation(goBackToDiceTray, i, diceInstance, delegate
			{
				SpawnVFXAndUpdateDiceInstance(diceInstance);
			});
		}
		else
		{
			SpawnVFXAndUpdateDiceInstance(diceInstance);
		}
	}

	private void SpawnVFXAndUpdateDiceInstance(DiceInstance diceInstance)
	{
		if (IsVFXEnabled())
		{
			GetVFX(4f).GetComponent<ParticleFollower>().Initialize(diceInstance);
		}
		diceInstance.ActionFace.UnlockActionModifiers();
		diceInstance.UpdateActionValueModifier();
		diceInstance.ActionFace.UpdateActionValueModifier();
		diceInstance.UpdateDiceFace();
	}

	private void EndOfActionAndReset(bool goBackToDiceTray)
	{
		EndAction(goBackToDiceTray);
		ResetVariables();
	}
}
